import urllib.request
def zfetch(id):
    d=json.load(urllib.request.urlopen(urllib.request.Request('https://zenodo.org/api/records/'+id,headers={'User-Agent':'agentprov-research/1.0'}),timeout=60))
    m=d['metadata']
    return {'id':id,'doi':d.get('doi'),'title':m['title'],'date':m['publication_date'],'rt':m.get('resource_type',{}).get('type'),'lic':(m.get('license') or {}).get('id'),'creators':[c['name'] for c in m['creators']][:6],'files':[(f['key'],f['size']) for f in d.get('files',[])],'rel':[(r['relation'],r['identifier']) for r in m.get('related_identifiers',[])]}
def exts(files):
    s=set()
    for n,_ in files:
        m=re.search(r'\.([A-Za-z0-9]+)(?:\.part.*)?$',n)
        if m: s.add(m.group(1).lower())
    return sorted(s)
def relsplit(rel):
    paper=[x[1] for x in rel if re.match(r'(arXiv:|10\.\d+/(?!zenodo))|https?://(arxiv|doi)',x[1])]
    repo=[x[1] for x in rel if 'github.com' in x[1] or 'huggingface.co' in x[1]]
    return ('; '.join(paper[:3]) or None),('; '.join(repo[:2]) or None)
def Zr(id,decision,per_run,fmt,known='no',notes='',excl=None,size=None,title=None,gated=False,extra=None):
    r=ZD.get(id) or Z.get(id) or zfetch(id)
    files=r['files']
    sz=size if size is not None else sum(s for _,s in files)
    p,rp=relsplit(r['rel'])
    d={'id':f'ZEN-{id}','repository':'Zenodo','title':title or r['title'],'doi_or_url':f"https://doi.org/{r.get('doi') or '10.5281/zenodo.'+id}",'date':r['date'],'creators':r['creators'][:6],'licence':r.get('lic'),'size_bytes':sz,'file_formats':exts(files),'per_run_logs':per_run,'format_family':fmt,'related_paper':p,'related_repo':rp,'gated':gated,'decision':decision,'exclusion_reason':excl,'known_already':known,'notes':notes,'resource_type':r.get('rt'),'file_names_sample':[n for n,_ in files[:6]]}
    if extra: d.update(extra)
    recs.append(d)
def Hr(id,decision,per_run,fmt,known='no',notes='',excl=None,licence=None,title=None,extra=None,size=None):
    r=HD.get(id)
    if r is None:
        d={'id':f'HF-{id}','repository':'HuggingFace','title':title or id,'doi_or_url':f'https://huggingface.co/datasets/{id}','date':None,'creators':[id.split('/')[0]],'licence':licence,'size_bytes':size,'file_formats':[],'per_run_logs':per_run,'format_family':fmt,'related_paper':None,'related_repo':None,'gated':None,'decision':decision,'exclusion_reason':excl,'known_already':known,'notes':notes,'metadata_fetched':False}
    else:
        lic=[t.replace('license:','') for t in r['tags'] if t.startswith('license:')]
        d={'id':f'HF-{id}','repository':'HuggingFace','title':title or id,'doi_or_url':f'https://huggingface.co/datasets/{id}','date':(r['created'] or '')[:10]+' (created); '+(r['last'] or '')[:10]+' (modified)','creators':[r['author']],'licence':licence or (lic[0] if lic else None),'size_bytes':size if size is not None else r['sumsize'],'file_formats':sorted(k for k in r['exts'] if k and k not in ('gitattributes',)),'n_files':r['nfiles'],'per_run_logs':per_run,'format_family':fmt,'related_paper':None,'related_repo':None,'gated':r['gated'],'decision':decision,'exclusion_reason':excl,'known_already':known,'notes':notes,'sha':r.get('sha'),'downloads_30d_or_alltime_field':r['downloads']}
    if extra: d.update(extra)
    recs.append(d)
def O(**kw):
    d={'creators':[],'licence':None,'size_bytes':None,'file_formats':[],'related_paper':None,'related_repo':None,'gated':False,'exclusion_reason':None,'known_already':'no','notes':'','date':None}
    d.update(kw); recs.append(d)

